-- ============================================================================
-- RF Performance — Avaliações e Certificações
-- Catálogo Ampliado — Método VAP — Teste 9
-- Fase 2D — cadastro em RASCUNHO para homologação controlada
--
-- Teste 9:
--   Etapas da Venda e Contorno de Objeções
--   15 questões de Processo de Venda + 15 questões de Objeções/CALMA.
--
-- Fonte primária já cadastrada na Fase 2A:
--   O Método VAP — Vendedor de Alta Performance
--   SHA-256: d28448b0b2e377af5233b939543bafb165d75d865547ef1627335f5a8b912b84
--
-- Documento de autoria das questões:
--   Sistema de Certificação Comercial — Método VAP — Testes 6 a 10
--   SHA-256: 8b8744e0779fce01a2f505d22a700e4e88878c7848a9845968e2b2e66a263820
--
-- SEGURANÇA / ESCOPO
--   - Não altera Testes 1 a 8.
--   - Não recria a fonte Método VAP.
--   - Não cria grant de acesso.
--   - Não publica o Teste 9.
--   - Não cria tentativa.
--   - Gabarito permanece em private.assessment_question_keys.
--   - Corte 100/100 propositalmente fail-closed até definição da política.
-- ============================================================================

begin;

do $guard$
declare
  v_org_id uuid := '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid;
begin
  if not exists (
    select 1
    from public.organizations o
    where o.id = v_org_id
      and o.slug = 'rf-consorcios'
      and o.status = 'active'
      and o.archived_at is null
  ) then
    raise exception 'VAP Teste 9 abortado: organização RF esperada não localizada/ativa.';
  end if;

  if (
    select count(*)
    from public.assessment_tests t
    where t.organization_id = v_org_id
      and t.archived_at is null
      and t.sequence_no between 1 and 8
  ) <> 8 then
    raise exception 'VAP Teste 9 abortado: catálogo-base Testes 1 a 8 não está íntegro.';
  end if;

  if not exists (
    select 1
    from public.assessment_tests t
    join public.assessment_test_versions tv
      on tv.test_id = t.id
     and tv.organization_id = t.organization_id
     and tv.archived_at is null
    where t.organization_id = v_org_id
      and t.sequence_no = 8
      and t.code = 'teste_8_vap_neurovendas_copywriting'
      and t.status = 'draft'
      and tv.version_code = '2026.08-v1'
      and tv.status = 'draft'
      and t.archived_at is null
  ) then
    raise exception 'VAP Teste 9 abortado: Teste 8 VAP esperado não está presente em draft.';
  end if;

  if not exists (
    select 1
    from public.source_material_versions smv
    join public.source_materials sm
      on sm.id = smv.source_material_id
     and sm.organization_id = smv.organization_id
    where sm.id = '2831b27b-035b-54fd-a3cc-d8a23a509a82'::uuid
      and smv.id = 'a20ad8ff-b3f8-5106-b96e-346fa342d098'::uuid
      and sm.organization_id = v_org_id
      and sm.code = 'metodo_vap_vendedor_alta_performance'
      and sm.material_type = 'book'
      and sm.status = 'active'
      and smv.version_code = '1a-edicao-2024'
      and smv.status = 'active'
      and lower(smv.content_sha256) = 'd28448b0b2e377af5233b939543bafb165d75d865547ef1627335f5a8b912b84'
      and sm.archived_at is null
      and smv.archived_at is null
  ) then
    raise exception 'VAP Teste 9 abortado: fonte Método VAP/versionamento esperado não confere.';
  end if;

  if exists (
    select 1
    from public.assessment_tests t
    where t.organization_id = v_org_id
      and t.archived_at is null
      and (
        t.sequence_no = 9
        or t.code = 'teste_9_vap_etapas_venda_objecoes'
        or t.id = 'de4e5063-786f-54e9-b9b0-257eccd982d3'::uuid
      )
  ) then
    raise exception 'VAP Teste 9 abortado: já existe teste ocupando a identidade/seq. 9.';
  end if;

  if exists (
    select 1
    from public.competency_domains c
    where c.organization_id = v_org_id
      and c.archived_at is null
      and (
        c.sequence_no between 39 and 40
        or c.code in ('vap_etapas_venda','vap_objecoes_calma')
        or c.id in (
          '7c065d74-728d-542f-947d-aa778840fc3b'::uuid,
          'a89f1693-ebaf-58ae-922f-99630d448998'::uuid
        )
      )
  ) then
    raise exception 'VAP Teste 9 abortado: identidade/sequência das novas competências já está ocupada.';
  end if;
end
$guard$;

