insert into public.assessment_version_questions (
  id, organization_id, test_version_id, question_id,
  sequence_no, points, is_required, metadata
)
select
  id, organization_id, test_version_id, question_id,
  sequence_no, points, is_required, metadata
from payload;

do $post$
declare
  v_org_id uuid := '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid;
  v_test_id uuid := 'de4e5063-786f-54e9-b9b0-257eccd982d3'::uuid;
  v_version_id uuid := '0b76646a-faa0-582f-8c9f-95ddac016717'::uuid;
begin
  if (
    select count(*)
    from public.competency_domains c
    where c.organization_id = v_org_id
      and c.code in ('vap_etapas_venda','vap_objecoes_calma')
      and c.status = 'draft'
      and c.is_legal = false
      and c.archived_at is null
  ) <> 2 then
    raise exception 'VAP Teste 9 pós-condição: esperado 2 competências VAP em draft.';
  end if;

  if not exists (
    select 1
    from public.assessment_tests t
    where t.id = v_test_id
      and t.organization_id = v_org_id
      and t.code = 'teste_9_vap_etapas_venda_objecoes'
      and t.sequence_no = 9
      and t.question_count = 30
      and t.status = 'draft'
      and t.archived_at is null
  ) then
    raise exception 'VAP Teste 9 pós-condição: identidade do teste não confere.';
  end if;

  if not exists (
    select 1
    from public.assessment_test_versions tv
    where tv.id = v_version_id
      and tv.organization_id = v_org_id
      and tv.test_id = v_test_id
      and tv.version_code = '2026.08-v1'
      and tv.version_no = 1
      and tv.status = 'draft'
      and tv.passing_score = 100
      and tv.legal_min_score = 100
      and tv.question_count = 30
      and tv.randomize_questions = true
      and tv.randomize_options = true
      and tv.published_at is null
      and tv.archived_at is null
  ) then
    raise exception 'VAP Teste 9 pós-condição: versão draft/fail-closed não confere.';
  end if;

  if (
    select count(*)
    from public.assessment_questions q
    where q.organization_id = v_org_id
      and q.code like 'vap_t9_q%'
      and q.status = 'reviewed'
      and q.archived_at is null
  ) <> 30 then
    raise exception 'VAP Teste 9 pós-condição: esperado 30 questões reviewed.';
  end if;

  if (
    select count(*)
    from public.assessment_version_questions avq
    where avq.organization_id = v_org_id
      and avq.test_version_id = v_version_id
      and avq.is_required = true
      and avq.archived_at is null
  ) <> 30 then
    raise exception 'VAP Teste 9 pós-condição: esperado 30 vínculos obrigatórios.';
  end if;

  if (
    select count(distinct avq.sequence_no)
    from public.assessment_version_questions avq
    where avq.organization_id = v_org_id
      and avq.test_version_id = v_version_id
      and avq.archived_at is null
  ) <> 30
  or (
    select min(avq.sequence_no)
    from public.assessment_version_questions avq
    where avq.organization_id = v_org_id
      and avq.test_version_id = v_version_id
      and avq.archived_at is null
  ) <> 1
  or (
    select max(avq.sequence_no)
    from public.assessment_version_questions avq
    where avq.organization_id = v_org_id
      and avq.test_version_id = v_version_id
      and avq.archived_at is null
  ) <> 30 then
    raise exception 'VAP Teste 9 pós-condição: sequência de questões não é 1..30.';
  end if;

  if (
    select count(*)
    from public.assessment_question_options o
    join public.assessment_questions q
      on q.id = o.question_id
     and q.organization_id = o.organization_id
    where o.organization_id = v_org_id
      and q.code like 'vap_t9_q%'
      and q.archived_at is null
      and o.archived_at is null
  ) <> 120 then
    raise exception 'VAP Teste 9 pós-condição: esperado 120 alternativas.';
  end if;

  if exists (
    select 1
    from (
      select q.id, count(o.id) as option_count
      from public.assessment_questions q
      left join public.assessment_question_options o
        on o.question_id = q.id
       and o.organization_id = q.organization_id
       and o.archived_at is null
      where q.organization_id = v_org_id
        and q.code like 'vap_t9_q%'
        and q.archived_at is null
      group by q.id
    ) x
    where x.option_count <> 4
  ) then
    raise exception 'VAP Teste 9 pós-condição: alguma questão não possui exatamente 4 alternativas.';
  end if;

  if (
    select count(*)
    from private.assessment_question_keys k
    join public.assessment_questions q
      on q.id = k.question_id
     and q.organization_id = k.organization_id
    where k.organization_id = v_org_id
      and q.code like 'vap_t9_q%'
      and q.archived_at is null
  ) <> 30 then
    raise exception 'VAP Teste 9 pós-condição: esperado 30 gabaritos privados.';
  end if;

  if exists (
    select 1
    from private.assessment_question_keys k
    join public.assessment_questions q
      on q.id = k.question_id
     and q.organization_id = k.organization_id
    left join public.assessment_question_options o
      on o.question_id = k.question_id
     and o.organization_id = k.organization_id
     and o.option_code = k.correct_option_code
     and o.archived_at is null
    where k.organization_id = v_org_id
      and q.code like 'vap_t9_q%'
      and q.archived_at is null
      and o.id is null
  ) then
    raise exception 'VAP Teste 9 pós-condição: existe gabarito sem alternativa correspondente.';
  end if;

  if exists (
    select 1
    from private.assessment_question_keys k
    join public.assessment_questions q
      on q.id = k.question_id
     and q.organization_id = k.organization_id
    where k.organization_id = v_org_id
      and q.code like 'vap_t9_q%'
      and q.archived_at is null
      and k.is_critical = true
  ) then
    raise exception 'VAP Teste 9 pós-condição: criticidade foi criada sem base no material.';
  end if;

  if (
    select count(*)
    from public.assessment_version_sources avs
    where avs.organization_id = v_org_id
      and avs.test_version_id = v_version_id
      and avs.source_material_version_id = 'a20ad8ff-b3f8-5106-b96e-346fa342d098'::uuid
      and avs.relation_type = 'primary'
      and avs.is_required = true
      and avs.archived_at is null
  ) <> 1 then
    raise exception 'VAP Teste 9 pós-condição: vínculo com fonte primária não confere.';
  end if;

  if exists (
    select 1
    from private.assessment_test_access_grants g
    where g.organization_id = v_org_id
      and g.test_id = v_test_id
      and g.archived_at is null
  ) then
    raise exception 'VAP Teste 9 pós-condição: nenhum grant deveria ter sido criado.';
  end if;

  if exists (
    select 1
    from public.assessment_attempts a
    where a.organization_id = v_org_id
      and a.test_id = v_test_id
      and a.archived_at is null
  ) then
    raise exception 'VAP Teste 9 pós-condição: nenhuma tentativa deveria existir.';
  end if;

  if (
    select count(*)
    from public.assessment_tests t
    where t.organization_id = v_org_id
      and t.sequence_no between 1 and 8
      and t.archived_at is null
  ) <> 8 then
    raise exception 'VAP Teste 9 pós-condição: catálogo-base 1..8 foi alterado.';
  end if;
end
$post$;

commit;
